    int remaining = raw.capacity() - allocated;
    quotas.set(0, new VersionQuota(raw.versionNo(), false, null, null,
            raw.capacity(), allocated, remaining, 0));
    totalAllocated += nullVersionAllocations;
    totalRemaining -= nullVersionAllocations;
}
int difference = totalCapacity - totalAllocated - totalRemaining - totalAbandoned;

